15		"time"
16	)
17	
18	// Minimal RFC 6455 WebSocket server-side codec. The subscription endpoint is
19	// the only WebSocket surface and it is push-only: the server sends text
20	// frames, the client may send control frames (ping/close), and any inbound
21	// data frame is read and discarded. No external dependency is introduced, so
22	// the module keeps its single SQLite dependency.
23	
24	const (
25		wsOpcodeContinue = 0x0
26		wsOpcodeText     = 0x1
27		wsOpcodeBinary   = 0x2
28		wsOpcodeClose    = 0x8
29		wsOpcodePing     = 0x9
30		wsOpcodePong     = 0xA
31	
32		wsFlagFin  = 0x80
33		wsFlagMask = 0x80
34	
35		// wsMaxInboundMessage caps a frame/assembled message sent by the client.
36		// Clients are not expected to send anything but control frames; the cap
37		// only protects the reader.
38		wsMaxInboundMessage = 1 << 20
39		// wsMaxControlPayload is the RFC cap on ping/pong/close payloads.
40		wsMaxControlPayload = 125
41	
42		wsWriteTimeout = 10 * time.Second
43		wsGUID         = "258EAFA5-E914-47DA-95CA-C5AB0DC85B11"
44	)
45	
46	// Close codes the subscription endpoint emits.
47	const (
48		// wsCloseGoingAway (1001) ends every subscription when the process
49		// receives its termination signal.
50		wsCloseGoingAway = 1001
51		// wsCloseProtocolError (1002) ends a connection whose frames violate
52		// RFC 6455.
53		wsCloseProtocolError = 1002
54		// wsCloseInternalError (1011) ends a connection that hit an unexpected
55		// server failure after the handshake.
56		wsCloseInternalError = 1011
57		// wsClosePermissionRevoked (4403) ends a subscription after its
58		// session's device loses permission for the document.
59		wsClosePermissionRevoked = 4403
60	)
61	
62	// ErrWebSocketClosed is returned by ReadMessage when the peer sends a close
63	// frame; Code/Reason carry the peer's payload when present.
64	var ErrWebSocketClosed = errors.New("websocket close received")
65	
66	type wsCloseError struct {
67		Code   int
68		Reason string
69	}
70	
71	func (e *wsCloseError) Error() string {
72		return fmt.Sprintf("%s: code=%d reason=%q", ErrWebSocketClosed, e.Code, e.Reason)
73	}
74	func (e *wsCloseError) Unwrap() error { return ErrWebSocketClosed }
75	
76	// wsConn is one upgraded WebSocket connection. Writes are serialized; reads
77	// are single-owner (the read pump).
78	type wsConn struct {
79		conn      net.Conn
80		br        *bufio.Reader
81		writeMu   sync.Mutex
82		sentClose bool
83	}
84	
85	// headerContainsToken reports whether a comma-list HTTP header (Connection is
86	// one) carries token, compared case-insensitively per RFC 7230 token rules.
87	func headerContainsToken(header, token string) bool {
88		for _, part := range strings.Split(header, ",") {
89			if strings.EqualFold(strings.TrimSpace(part), token) {
90				return true
91			}
92		}
93		return false
94	}
95	
96	// checkWebSocketUpgrade validates the RFC 6455 opening handshake headers
97	// without hijacking the connection: a failed check is an ordinary 400 JSON
98	// error, so malformed requests never see a redirect, HTML or a 101. It does
99	// not touch the response otherwise.
100	func checkWebSocketUpgrade(r *http.Request) bool {
101		if !headerContainsToken(r.Header.Get("Connection"), "upgrade") ||
102			!strings.EqualFold(r.Header.Get("Upgrade"), "websocket") {
103			return false
104		}
105		if r.Header.Get("Sec-WebSocket-Version") != "13" {
106			return false
107		}
108		key := r.Header.Get("Sec-WebSocket-Key")
109		decoded, err := base64.StdEncoding.DecodeString(key)
110		if err != nil || len(decoded) != 16 {
111			return false
112		}
113		return true
114	}
