116	// secWebSocketAccept computes the Sec-WebSocket-Accept handshake value.
117	func secWebSocketAccept(key string) string {
118		sum := sha1.Sum([]byte(key + wsGUID))
119		return base64.StdEncoding.EncodeToString(sum[:])
120	}
