package server

import (
	"bufio"
	"crypto/sha1"
	"encoding/base64"
	"encoding/binary"
	"errors"
	"fmt"
	"io"
	"net"
	"net/http"
	"strings"
	"sync"
	"time"
)

// Minimal RFC 6455 WebSocket server-side codec. The subscription endpoint is
// the only WebSocket surface and it is push-only: the server sends text
// frames, the client may send control frames (ping/close), and any inbound
// data frame is read and discarded. No external dependency is introduced, so
// the module keeps its single SQLite dependency.

const (
	wsOpcodeContinue = 0x0
	wsOpcodeText     = 0x1
	wsOpcodeBinary   = 0x2
	wsOpcodeClose    = 0x8
	wsOpcodePing     = 0x9
	wsOpcodePong     = 0xA

	wsFlagFin  = 0x80
	wsFlagMask = 0x80

	// wsMaxInboundMessage caps a frame/assembled message sent by the client.
	// Clients are not expected to send anything but control frames; the cap
	// only protects the reader.
	wsMaxInboundMessage = 1 << 20
	// wsMaxControlPayload is the RFC cap on ping/pong/close payloads.
	wsMaxControlPayload = 125

	wsWriteTimeout = 10 * time.Second
	wsGUID         = "258EAFA5-E914-47DA-95CA-C5AB0DC85B11"
)

// Close codes the subscription endpoint emits.
const (
	// wsCloseGoingAway (1001) ends every subscription when the process
	// receives its termination signal.
	wsCloseGoingAway = 1001
	// wsCloseProtocolError (1002) ends a connection whose frames violate
	// RFC 6455.
	wsCloseProtocolError = 1002
	// wsCloseInternalError (1011) ends a connection that hit an unexpected
	// server failure after the handshake.
	wsCloseInternalError = 1011
	// wsClosePermissionRevoked (4403) ends a subscription after its
	// session's device loses permission for the document.
	wsClosePermissionRevoked = 4403
)

// ErrWebSocketClosed is returned by ReadMessage when the peer sends a close
// frame; Code/Reason carry the peer's payload when present.
var ErrWebSocketClosed = errors.New("websocket close received")

type wsCloseError struct {
	Code   int
	Reason string
}

func (e *wsCloseError) Error() string {
	return fmt.Sprintf("%s: code=%d reason=%q", ErrWebSocketClosed, e.Code, e.Reason)
}
func (e *wsCloseError) Unwrap() error { return ErrWebSocketClosed }

// wsConn is one upgraded WebSocket connection. Writes are serialized; reads
// are single-owner (the read pump).
type wsConn struct {
	conn      net.Conn
	br        *bufio.Reader
	writeMu   sync.Mutex
	sentClose bool
}

// headerContainsToken reports whether a comma-list HTTP header (Connection is
// one) carries token, compared case-insensitively per RFC 7230 token rules.
func headerContainsToken(header, token string) bool {
	for _, part := range strings.Split(header, ",") {
		if strings.EqualFold(strings.TrimSpace(part), token) {
			return true
		}
	}
	return false
}

// checkWebSocketUpgrade validates the RFC 6455 opening handshake headers
// without hijacking the connection: a failed check is an ordinary 400 JSON
// error, so malformed requests never see a redirect, HTML or a 101. It does
// not touch the response otherwise.
func checkWebSocketUpgrade(r *http.Request) bool {
	if !headerContainsToken(r.Header.Get("Connection"), "upgrade") ||
		!strings.EqualFold(r.Header.Get("Upgrade"), "websocket") {
		return false
	}
	if r.Header.Get("Sec-WebSocket-Version") != "13" {
		return false
	}
	key := r.Header.Get("Sec-WebSocket-Key")
	decoded, err := base64.StdEncoding.DecodeString(key)
	if err != nil || len(decoded) != 16 {
		return false
	}
	return true
}

// secWebSocketAccept computes the Sec-WebSocket-Accept handshake value.
func secWebSocketAccept(key string) string {
	sum := sha1.Sum([]byte(key + wsGUID))
	return base64.StdEncoding.EncodeToString(sum[:])
}

// upgradeWebSocket hijacks the connection and writes the 101 response. Every
// precondition (method, cursor, session, permission, handshake headers) has
// already been checked by the caller; from here on failures are reported as
// WebSocket close frames rather than HTTP statuses.
func upgradeWebSocket(w http.ResponseWriter, r *http.Request) (*wsConn, error) {
	hj, ok := w.(http.Hijacker)
	if !ok {
		return nil, errors.New("connection does not support hijacking")
	}
	conn, brw, err := hj.Hijack()
	if err != nil {
		return nil, err
	}

	accept := secWebSocketAccept(r.Header.Get("Sec-WebSocket-Key"))
	response := "HTTP/1.1 101 Switching Protocols\r\n" +
		"Upgrade: websocket\r\n" +
		"Connection: Upgrade\r\n" +
		"Sec-WebSocket-Accept: " + accept + "\r\n\r\n"
	if _, err := io.WriteString(conn, response); err != nil {
		_ = conn.Close()
		return nil, err
	}
	// Flush anything the HTTP layer buffered before the hijack.
	if err := brw.Flush(); err != nil {
		_ = conn.Close()
		return nil, err
	}
	return &wsConn{conn: conn, br: brw.Reader}, nil
}

// readFrame reads one RFC 6455 frame, unmasking client payloads.
func (c *wsConn) readFrame() (fin bool, opcode byte, payload []byte, err error) {
	header := make([]byte, 2)
	if _, err = io.ReadFull(c.br, header); err != nil {
		return false, 0, nil, err
	}
	b0, b1 := header[0], header[1]
	if b0&0x70 != 0 {
		return false, 0, nil, wsProtocolError("reserved bits must be zero")
	}
	fin = b0&wsFlagFin != 0
	opcode = b0 & 0x0F
	masked := b1&wsFlagMask != 0
	length := int64(b1 & 0x7F)

	switch length {
	case 126:
		var ext [2]byte
		if _, err = io.ReadFull(c.br, ext[:]); err != nil {
			return false, 0, nil, err
		}
		length = int64(binary.BigEndian.Uint16(ext[:]))
	case 127:
		var ext [8]byte
		if _, err = io.ReadFull(c.br, ext[:]); err != nil {
			return false, 0, nil, err
		}
		length = int64(binary.BigEndian.Uint64(ext[:]))
		if length < 0 {
			return false, 0, nil, wsProtocolError("frame length too large")
		}
	}
	if opcode == wsOpcodeClose && length > wsMaxControlPayload {
		return false, 0, nil, wsProtocolError("close frame too large")
	}
	if opcode >= wsOpcodeClose && !fin {
		return false, 0, nil, wsProtocolError("control frame must not be fragmented")
	}
	if length > wsMaxInboundMessage {
		return false, 0, nil, wsProtocolError("frame too large")
	}

	var mask [4]byte
	if masked {
		if _, err = io.ReadFull(c.br, mask[:]); err != nil {
			return false, 0, nil, err
		}
	}
	payload = make([]byte, length)
	if length > 0 {
		if _, err = io.ReadFull(c.br, payload); err != nil {
			return false, 0, nil, err
		}
	}
	if masked {
		for i := range payload {
			payload[i] ^= mask[i%4]
		}
	} else {
		// RFC 6455 §5.1: a frame from a client MUST be masked.
		return false, 0, nil, wsProtocolError("client frame is not masked")
	}
	return fin, opcode, payload, nil
}

// ReadMessage returns the next complete data message, answering control
// frames inline: a ping is answered with a pong, a pong is ignored, and a
// close frame surfaces as ErrWebSocketClosed (the caller echoes it). Fragmented
// messages are reassembled in receive order.
func (c *wsConn) ReadMessage() (opcode byte, payload []byte, err error) {
	var assembled []byte
	started := false
	messageOpcode := byte(wsOpcodeText)

	for {
		fin, frameOpcode, framePayload, frameErr := c.readFrame()
		if frameErr != nil {
			return 0, nil, frameErr
		}

		switch frameOpcode {
		case wsOpcodeContinue:
			if !started {
				return 0, nil, wsProtocolError("continuation frame without a start frame")
			}
			assembled = append(assembled, framePayload...)
		case wsOpcodeText, wsOpcodeBinary:
			if started {
				return 0, nil, wsProtocolError("new data frame before the fragment finished")
			}
			started = true
			messageOpcode = frameOpcode
			assembled = append(assembled[:0], framePayload...)
		case wsOpcodeClose:
			closeErr := parseClosePayload(framePayload)
			if writeErr := c.writeCloseResponse(framePayload); writeErr != nil {
				_ = c.conn.Close()
			}
			return 0, nil, closeErr
		case wsOpcodePing:
			if len(framePayload) > wsMaxControlPayload {
				return 0, nil, wsProtocolError("ping payload too large")
			}
			if pingErr := c.writeControl(wsOpcodePong, framePayload); pingErr != nil {
				return 0, nil, pingErr
			}
			continue
		case wsOpcodePong:
			continue
		default:
			return 0, nil, wsProtocolError(fmt.Sprintf("unknown opcode %d", frameOpcode))
		}

		if len(assembled) > wsMaxInboundMessage {
			return 0, nil, wsProtocolError("message too large")
		}
		if fin {
			return messageOpcode, assembled, nil
		}
	}
}

func parseClosePayload(payload []byte) error {
	if len(payload) == 0 {
		return &wsCloseError{Code: wsCloseGoingAway, Reason: ""}
	}
	if len(payload) < 2 {
		return wsProtocolError("close payload too short")
	}
	code := int(binary.BigEndian.Uint16(payload[:2]))
	return &wsCloseError{Code: code, Reason: string(payload[2:])}
}

// writeFrame sends one server frame; server frames are never masked.
func (c *wsConn) writeFrame(opcode byte, fin bool, payload []byte) error {
	_ = c.conn.SetWriteDeadline(time.Now().Add(wsWriteTimeout))

	var b0 byte = opcode
	if fin {
		b0 |= wsFlagFin
	}

	var header [10]byte
	header[0] = b0
	n := 1
	switch {
	case len(payload) <= 125:
		header[1] = byte(len(payload))
		n++
	case len(payload) <= 65535:
		header[1] = 126
		binary.BigEndian.PutUint16(header[2:4], uint16(len(payload)))
		n += 3
	default:
		header[1] = 127
		binary.BigEndian.PutUint64(header[2:10], uint64(len(payload)))
		n += 9
	}
	if _, err := c.conn.Write(header[:n]); err != nil {
		return err
	}
	if len(payload) > 0 {
		if _, err := c.conn.Write(payload); err != nil {
			return err
		}
	}
	return nil
}

func (c *wsConn) writeControl(opcode byte, payload []byte) error {
	c.writeMu.Lock()
	defer c.writeMu.Unlock()
	return c.writeFrame(opcode, true, payload)
}

// WriteText sends one complete text frame.
func (c *wsConn) WriteText(payload []byte) error {
	c.writeMu.Lock()
	defer c.writeMu.Unlock()
	if c.sentClose {
		return errors.New("write after close frame")
	}
	return c.writeFrame(wsOpcodeText, true, payload)
}

// writeCloseResponse echoes a client close frame when the server has not yet
// sent its own; it is the read-pump side of the closing handshake.
func (c *wsConn) writeCloseResponse(payload []byte) error {
	c.writeMu.Lock()
	defer c.writeMu.Unlock()
	if c.sentClose {
		return nil
	}
	c.sentClose = true
	return c.writeFrame(wsOpcodeClose, true, payload)
}

// Close sends the closing handshake with code/reason exactly once. It does not
// block on the peer's echo and never reads: the handler owns one read pump,
// and concurrent readers on the buffered connection are unsafe. The handler
// waits on its read pump and then calls NetClose.
func (c *wsConn) Close(code int, reason string) error {
	c.writeMu.Lock()
	defer c.writeMu.Unlock()
	if c.sentClose {
		return nil
	}
	c.sentClose = true
	payload := make([]byte, 2+len(reason))
	binary.BigEndian.PutUint16(payload, uint16(code))
	copy(payload[2:], reason)
	return c.writeFrame(wsOpcodeClose, true, payload)
}

// NetClose drops the underlying TCP connection. The read pump unblocks with a
// read error; a double close (read pump and handler) is harmless.
func (c *wsConn) NetClose() error { return c.conn.Close() }

type wsProtocolErrorString struct{ msg string }

func (e *wsProtocolErrorString) Error() string { return "websocket protocol error: " + e.msg }

func wsProtocolError(msg string) error { return &wsProtocolErrorString{msg: msg} }

// Package store is the durable kernel shared by the internal services: it
// owns the SQLite database handle and the registration layer (devices and
// sessions) plus resumable attachments.
//
// The business services layered on top of the kernel — the change event log,
// the permission ledger and the CRDT state — live in their own packages and
// cooperate only through their internal interfaces. They all share this one
// handle: it opens a single pooled connection with immediate write
// transactions, so every service's transactional judgment is serialized on
// the same connection and no batch is ever half written.
//
// Devices and sessions form the registration layer. A device registers with a
// client-supplied id; a session belongs to exactly one registered device and
// is addressed by its own client-supplied id. Registration and session
// creation are idempotent re-posts: the first call creates, an identical
// repeat does not. A session id already owned by another device is a
// conflict, never silently re-homed. Deletes are owner-scoped and hard: a
// repeat delete, another device, and a cross-device path all miss with 404,
// after which the id is free to be created again. A device itself can
// deregister: the device row and everything it owns — its sessions and the
// attachments it created, chunks and grants included — vanish in one
// serialized transaction, a repeat or never-registered deregistration misses
// with 404 and writes nothing, and the freed id registers again as a
// brand-new device.
//
// Attachments are resumable chunked uploads owned by the registered device
// that created them. Creation pins the declared total size, chunk size and
// SHA-256 digest; chunks land in any order and are stored durably as they
// arrive, so an interrupted upload resumes after a restart with its
// idempotency and conflict decisions intact. Finishing concatenates the
// chunks, verifies the digest and seals the upload; a sealed upload is
// immutable and rejects every further chunk write. Finished content is
// addressed by digest, so a second attachment with the same digest and size
// reuses the stored bytes instead of copying them. The creator may grant
// other registered devices read-only access per attachment; every
// (attachment, device) pair starts unauthorized, grants and revokes commit in
// the same serialized way, and access never widens the write paths. Deletes
// are owner-scoped and hard: the record, its chunks and its grants vanish in
// one serialized transaction, a repeat delete misses with 404, the id is free
// to be created again, and the shared content bytes are reclaimed once the
// last completed attachment referencing them is gone.
package store

import (
	"database/sql"
	"encoding/json"
	"errors"
	"fmt"

	_ "modernc.org/sqlite"
)

// ErrDeviceNotFound reports that an operation targets a device id that was
// never registered. Services map it to 404; nothing is written.
var ErrDeviceNotFound = errors.New("device not found")

// ErrPermissionDenied reports that a device's access to a document has been
// revoked. Services map it to 403; nothing is written and no document content
// is exposed. It is a shared verdict produced by the permission service and
// consulted by every service that enforces the gate inside a transaction.
var ErrPermissionDenied = errors.New("device permission for this document has been revoked")

// ErrSessionConflict reports that a session id already belongs to a different
// device. The session keeps its original owner; nothing is written. Services
// map it to 409.
type ErrSessionConflict struct {
	ID string
}

func (e *ErrSessionConflict) Error() string {
	return fmt.Sprintf("session %q belongs to another device", e.ID)
}

// ErrSessionNotFound reports that no live session matches the (device,
// session) pair: the session was never created, was already deleted, or
// belongs to another device. Services map it to 404.
var ErrSessionNotFound = errors.New("session not found")

// DBTX is the subset of *sql.DB and *sql.Tx the services use for their
// serialized work, so judgments made "in the same transaction" (for example a
// permission gate followed by the gated write) run on one concrete connection
// whether the caller holds a transaction or the handle itself.
type DBTX interface {
	Exec(query string, args ...any) (sql.Result, error)
	Query(query string, args ...any) (*sql.Rows, error)
	QueryRow(query string, args ...any) *sql.Row
}

// Store is the durable kernel: one SQLite database handle together with the
// device, session and attachment data it owns.
type Store struct {
	db *sql.DB
}

// Open opens (creating if needed) the SQLite database at path. The empty path
// opens an in-memory database useful for tests.
func Open(path string) (*Store, error) {
	if path == "" {
		// With a single pooled connection this is a private, per-instance
		// in-memory database (useful for tests).
		path = "file::memory:"
	}
	// _txlock=immediate makes writers acquire the write lock at BEGIN, so
	// concurrent batches serialize without SQLITE_BUSY deadlocks.
	dsn := path + "?_txlock=immediate&_busy_timeout=5000&_journal_mode=WAL&_synchronous=FULL&_foreign_keys=on"
	db, err := sql.Open("sqlite", dsn)
	if err != nil {
		return nil, err
	}
	// One connection avoids cross-connection locking surprises; writes are
	// serialized by the immediate transaction anyway, and SQLite concurrency
	// for readers does not help correctness here. It also keeps every
	// service's transaction serialized on the same connection.
	db.SetMaxOpenConns(1)
	s := &Store{db: db}
	if err := s.init(); err != nil {
		_ = db.Close()
		return nil, err
	}
	return s, nil
}

// DB returns the underlying handle. The business services use it to open the
// serialized transactions their judgments run in; callers outside the
// internal packages never need it.
func (s *Store) DB() *sql.DB { return s.db }

// Close releases the database handle.
func (s *Store) Close() error {
	return s.db.Close()
}

func (s *Store) init() error {
	_, err := s.db.Exec(`
CREATE TABLE IF NOT EXISTS devices (
	id TEXT NOT NULL PRIMARY KEY
);
CREATE TABLE IF NOT EXISTS sessions (
	id        TEXT NOT NULL PRIMARY KEY,
	device_id TEXT NOT NULL REFERENCES devices(id)
);
CREATE INDEX IF NOT EXISTS sessions_device_idx
	ON sessions(device_id);
CREATE TABLE IF NOT EXISTS attachments (
	id          TEXT NOT NULL PRIMARY KEY,
	device_id   TEXT NOT NULL REFERENCES devices(id),
	total_bytes INTEGER NOT NULL,
	chunk_size  INTEGER NOT NULL,
	sha256      TEXT NOT NULL,
	complete    INTEGER NOT NULL DEFAULT 0,
	reused      INTEGER NOT NULL DEFAULT 0,
	created_seq INTEGER NOT NULL DEFAULT 0
);
CREATE TABLE IF NOT EXISTS attachment_chunks (
	attachment_id TEXT NOT NULL REFERENCES attachments(id),
	idx           INTEGER NOT NULL,
	data          BLOB NOT NULL,
	PRIMARY KEY (attachment_id, idx)
);
CREATE TABLE IF NOT EXISTS attachment_contents (
	sha256 TEXT NOT NULL PRIMARY KEY,
	size   INTEGER NOT NULL,
	data   BLOB NOT NULL
);
CREATE TABLE IF NOT EXISTS attachment_access (
	attachment_id TEXT NOT NULL REFERENCES attachments(id),
	device_id     TEXT NOT NULL,
	authorized    INTEGER NOT NULL,
	granted_seq   INTEGER NOT NULL DEFAULT 0,
	PRIMARY KEY (attachment_id, device_id)
);
`)
	if err != nil {
		return err
	}
	if err := s.ensureAttachmentCreatedSeq(); err != nil {
		return err
	}
	return s.ensureAttachmentAccessGrantedSeq()
}

// ensureAttachmentCreatedSeq adds the creation-order column to databases
// created before it existed. Existing rows are backfilled in insertion
// (rowid) order so their relative listing order is unchanged; new rows take
// strictly larger values, so the sequence never reuses a value even after
// the newest attachment is deleted and its id created again.
func (s *Store) ensureAttachmentCreatedSeq() error {
	rows, err := s.db.Query(`PRAGMA table_info(attachments)`)
	if err != nil {
		return err
	}
	hasColumn := false
	for rows.Next() {
		var cid, notNull, pk int
		var name, colType string
		var dflt sql.NullString
		if err := rows.Scan(&cid, &name, &colType, &notNull, &dflt, &pk); err != nil {
			_ = rows.Close()
			return err
		}
		if name == "created_seq" {
			hasColumn = true
		}
	}
	if err := rows.Err(); err != nil {
		_ = rows.Close()
		return err
	}
	_ = rows.Close()
	if hasColumn {
		return nil
	}
	if _, err := s.db.Exec(
		`ALTER TABLE attachments ADD COLUMN created_seq INTEGER NOT NULL DEFAULT 0`,
	); err != nil {
		return err
	}
	_, err = s.db.Exec(
		`UPDATE attachments SET created_seq = (
			SELECT COUNT(*) FROM attachments older WHERE older.rowid <= attachments.rowid
		)`,
	)
	return err
}

// ensureAttachmentAccessGrantedSeq adds the grant-order column to access
// tables created before it existed. Existing rows are backfilled one past the
// per-attachment maximum in insertion (rowid) order, so surviving grants keep
// a stable relative order; every new grant takes a strictly larger value, even
// after the previously newest grant was revoked, so a re-granted device lists
// at the position of its latest grant and a value is never reused.
func (s *Store) ensureAttachmentAccessGrantedSeq() error {
	rows, err := s.db.Query(`PRAGMA table_info(attachment_access)`)
	if err != nil {
		return err
	}
	hasColumn := false
	for rows.Next() {
		var cid, notNull, pk int
		var name, colType string
		var dflt sql.NullString
		if err := rows.Scan(&cid, &name, &colType, &notNull, &dflt, &pk); err != nil {
			_ = rows.Close()
			return err
		}
		if name == "granted_seq" {
			hasColumn = true
		}
	}
	if err := rows.Err(); err != nil {
		_ = rows.Close()
		return err
	}
	_ = rows.Close()
	if hasColumn {
		return nil
	}
	if _, err := s.db.Exec(
		`ALTER TABLE attachment_access ADD COLUMN granted_seq INTEGER NOT NULL DEFAULT 0`,
	); err != nil {
		return err
	}
	_, err = s.db.Exec(
		`UPDATE attachment_access SET granted_seq = (
			SELECT rn FROM (
				SELECT rowid AS rid,
				       ROW_NUMBER() OVER (PARTITION BY attachment_id ORDER BY rowid) AS rn
				FROM attachment_access
			) WHERE rid = attachment_access.rowid
		)`,
	)
	return err
}

// RegisterDevice registers a device by client-supplied id. The first call for
// an id creates it and reports created=true; repeating the registration is
// idempotent (created=false). Device identity never changes.
func (s *Store) RegisterDevice(deviceID string) (created bool, err error) {
	tx, err := s.db.Begin()
	if err != nil {
		return false, err
	}
	defer func() { _ = tx.Rollback() }()

	created, err = RegisterDeviceTx(tx, deviceID)
	if err != nil {
		return false, err
	}
	return created, tx.Commit()
}

// RegisterDeviceTx is RegisterDevice against an existing transaction, so the
// services can resolve the registration layer as the first step of a larger
// serialized transaction (their permission/content gates then share it).
func RegisterDeviceTx(q DBTX, deviceID string) (created bool, err error) {
	var exists bool
	if err := q.QueryRow(
		`SELECT EXISTS(SELECT 1 FROM devices WHERE id = ?)`, deviceID,
	).Scan(&exists); err != nil {
		return false, err
	}
	if !exists {
		if _, err := q.Exec(`INSERT INTO devices (id) VALUES (?)`, deviceID); err != nil {
			return false, err
		}
		return true, nil
	}
	return false, nil
}

// DeviceExistsTx reports whether deviceID is registered, evaluated inside q so
// a service's gate runs on the same transaction as the work it guards.
func DeviceExistsTx(q DBTX, deviceID string) (bool, error) {
	var exists bool
	if err := q.QueryRow(
		`SELECT EXISTS(SELECT 1 FROM devices WHERE id = ?)`, deviceID,
	).Scan(&exists); err != nil {
		return false, err
	}
	return exists, nil
}

// CreateSession creates a session owned by deviceID with a client-supplied id.
//
//   - An unknown device yields ErrDeviceNotFound; nothing is written.
//   - A session id already owned by another device yields *ErrSessionConflict;
//     nothing is written and the owner is unchanged.
//   - Re-posting the same (device, session) pair is idempotent: created=false.
//
// A deleted session is gone for good, so its id can be registered again as a
// brand-new session (created=true). The lookup, owner check and insert run in
// one serialized transaction, so concurrent creates of the same session id
// cannot both create it.
func (s *Store) CreateSession(deviceID, sessionID string) (created bool, err error) {
	tx, err := s.db.Begin()
	if err != nil {
		return false, err
	}
	defer func() { _ = tx.Rollback() }()

	var deviceExists bool
	if err := tx.QueryRow(
		`SELECT EXISTS(SELECT 1 FROM devices WHERE id = ?)`, deviceID,
	).Scan(&deviceExists); err != nil {
		return false, err
	}
	if !deviceExists {
		return false, ErrDeviceNotFound
	}

	var owner string
	err = tx.QueryRow(
		`SELECT device_id FROM sessions WHERE id = ?`, sessionID,
	).Scan(&owner)
	switch {
	case errors.Is(err, sql.ErrNoRows):
		if _, err := tx.Exec(
			`INSERT INTO sessions (id, device_id) VALUES (?, ?)`,
			sessionID, deviceID,
		); err != nil {
			return false, err
		}
		if err := tx.Commit(); err != nil {
			return false, err
		}
		return true, nil
	case err != nil:
		return false, err
	}

	if owner != deviceID {
		return false, &ErrSessionConflict{ID: sessionID}
	}
	return false, tx.Commit()
}

// DeleteSession removes the live session matching the (deviceID, sessionID)
// pair. Any miss — the session does not exist, was already deleted, or belongs
// to another device — returns ErrSessionNotFound and changes nothing. The
// check and the delete run in one transaction, so a concurrent create cannot
// interleave and a repeat delete still misses; the removal is committed to
// disk before the call returns.
func (s *Store) DeleteSession(deviceID, sessionID string) error {
	tx, err := s.db.Begin()
	if err != nil {
		return err
	}
	defer func() { _ = tx.Rollback() }()

	var owner string
	err = tx.QueryRow(
		`SELECT device_id FROM sessions WHERE id = ?`, sessionID,
	).Scan(&owner)
	switch {
	case errors.Is(err, sql.ErrNoRows):
		return ErrSessionNotFound
	case err != nil:
		return err
	}
	if owner != deviceID {
		return ErrSessionNotFound
	}

	if _, err := tx.Exec(
		`DELETE FROM sessions WHERE id = ? AND device_id = ?`,
		sessionID, deviceID,
	); err != nil {
		return err
	}
	return tx.Commit()
}

// DeleteDeviceTx deregisters deviceID and removes every record it owns, all
// inside the caller's serialized transaction:
//
//   - the device's sessions are hard-deleted, so their session-scoped reads
//     and subscriptions miss from then on;
//   - every attachment it created is removed together with its chunks, its
//     sealed/unfinished state and the access rows other devices held on it;
//   - the read grants the device itself held on other devices' attachments
//     are withdrawn;
//   - the device row is removed last (every child row goes first).
//
// Digest-addressed content is shared across attachments and is reclaimed only
// when no completed attachment still references a digest — exactly the rule
// of a single attachment delete — so another device's attachment with the same
// digest keeps its bytes and one deregistration by itself never reclaims
// shared content. The document permission ledger lives in the authz package
// and clears its own rows against the same transaction through
// DeleteDevicePermissionsTx.
//
// An unknown (never registered or already deregistered) device yields
// ErrDeviceNotFound and writes nothing. Because the whole judgment runs in one
// immediate transaction on the single shared connection, concurrent
// deregistrations of the same device commit at most once and any concurrent
// chunk upload or finish either committed entirely before it or is rejected
// entirely afterward — no half-written record survives.
func DeleteDeviceTx(q DBTX, deviceID string) error {
	exists, err := DeviceExistsTx(q, deviceID)
	if err != nil {
		return err
	}
	if !exists {
		return ErrDeviceNotFound
	}

	// Remember the digests of the device's completed attachments before their
	// rows vanish: each is a candidate for content reclamation once every
	// owned attachment is gone. DISTINCT because several of the device's
	// attachments may share the same digest-addressed content.
	rows, err := q.Query(
		`SELECT DISTINCT sha256 FROM attachments WHERE device_id = ? AND complete = 1`,
		deviceID,
	)
	if err != nil {
		return err
	}
	var digests []string
	for rows.Next() {
		var digest string
		if err := rows.Scan(&digest); err != nil {
			_ = rows.Close()
			return err
		}
		digests = append(digests, digest)
	}
	if err := rows.Err(); err != nil {
		_ = rows.Close()
		return err
	}
	if err := rows.Close(); err != nil {
		return err
	}

	// Withdraw the read grants this device held on other devices'
	// attachments (rows naming it as the grantee), then remove the access
	// rosters of the attachments it created before the attachment rows those
	// rosters reference are deleted.
	if _, err := q.Exec(
		`DELETE FROM attachment_access WHERE device_id = ?`, deviceID,
	); err != nil {
		return err
	}
	if _, err := q.Exec(
		`DELETE FROM attachment_access
		 WHERE attachment_id IN (SELECT id FROM attachments WHERE device_id = ?)`,
		deviceID,
	); err != nil {
		return err
	}
	if _, err := q.Exec(
		`DELETE FROM attachment_chunks
		 WHERE attachment_id IN (SELECT id FROM attachments WHERE device_id = ?)`,
		deviceID,
	); err != nil {
		return err
	}
	if _, err := q.Exec(
		`DELETE FROM attachments WHERE device_id = ?`, deviceID,
	); err != nil {
		return err
	}

	// Reclaim each digest-addressed content only when no surviving completed
	// attachment — owned by another device, or by the deregistered device in
	// an impossible re-read — still references it.
	for _, digest := range digests {
		var stillReferenced bool
		if err := q.QueryRow(
			`SELECT EXISTS(SELECT 1 FROM attachments WHERE sha256 = ? AND complete = 1)`,
			digest,
		).Scan(&stillReferenced); err != nil {
			return err
		}
		if !stillReferenced {
			if _, err := q.Exec(
				`DELETE FROM attachment_contents WHERE sha256 = ?`, digest,
			); err != nil {
				return err
			}
		}
	}

	if _, err := q.Exec(
		`DELETE FROM sessions WHERE device_id = ?`, deviceID,
	); err != nil {
		return err
	}
	if _, err := q.Exec(
		`DELETE FROM devices WHERE id = ?`, deviceID,
	); err != nil {
		return err
	}
	return nil
}

// SessionExists reports whether a live session with sessionID exists.
// Ownership is intentionally not part of this check: session-scoped reads only
// require that the session currently exists.
func (s *Store) SessionExists(sessionID string) (bool, error) {
	var exists bool
	if err := s.db.QueryRow(
		`SELECT EXISTS(SELECT 1 FROM sessions WHERE id = ?)`, sessionID,
	).Scan(&exists); err != nil {
		return false, err
	}
	return exists, nil
}

// SessionDevice returns the id of the device that owns the live session
// sessionID. A session that was never created or was deleted yields
// ErrSessionNotFound.
func (s *Store) SessionDevice(sessionID string) (string, error) {
	var deviceID string
	err := s.db.QueryRow(
		`SELECT device_id FROM sessions WHERE id = ?`, sessionID,
	).Scan(&deviceID)
	switch {
	case errors.Is(err, sql.ErrNoRows):
		return "", ErrSessionNotFound
	case err != nil:
		return "", err
	default:
		return deviceID, nil
	}
}

// JSONEqual reports whether two payloads are equal after JSON decoding, so
// 1 and 1.0, or {"a":1,"b":2} and {"b":2,"a":1}, compare equal. It is shared
// verbatim by the change event and CRDT services' idempotency judgments.
func JSONEqual(a, b json.RawMessage) bool {
	var va, vb any
	if err := json.Unmarshal(a, &va); err != nil {
		return false
	}
	if err := json.Unmarshal(b, &vb); err != nil {
		return false
	}
	return deepEqual(va, vb)
}

func deepEqual(a, b any) bool {
	switch av := a.(type) {
	case nil:
		return b == nil
	case bool:
		bv, ok := b.(bool)
		return ok && av == bv
	case string:
		bv, ok := b.(string)
		return ok && av == bv
	case float64:
		bv, ok := b.(float64)
		return ok && av == bv
	case []any:
		bv, ok := b.([]any)
		if !ok || len(av) != len(bv) {
			return false
		}
		for i := range av {
			if !deepEqual(av[i], bv[i]) {
				return false
			}
		}
		return true
	case map[string]any:
		bv, ok := b.(map[string]any)
		if !ok || len(av) != len(bv) {
			return false
		}
		for k, v := range av {
			w, exists := bv[k]
			if !exists || !deepEqual(v, w) {
				return false
			}
		}
		return true
	default:
		return false
	}
}

// Package authz is the permission service: the durable, per-document and
// per-device authorization ledger together with the system's single revoke
// verdict.
//
// Every (document, device) pair starts authorized; a grant or revoke is
// recorded per pair. The lookup and the write run in one serialized
// transaction on the shared connection and commit to disk, so concurrent
// grant/revoke calls each land as a complete state and survive a restart.
//
// The other services do not read the permission table. They take their
// registration-and-authorization verdict through AuthorizedTx, evaluated
// inside their own write transaction, so a rejected request is judged before
// any document content is observed and the gate and the gated work commit as
// one judgment. Revoking never deletes changes, snapshots, sessions or CRDT
// state; it only produces the denial and, after the revoke commits, notifies
// the registered revoke sinks (the live subscription registries) so they can
// end the affected connections with the one-time, sticky 4403 close.
package authz

import (
	"database/sql"
	"errors"
	"sync"

	"github.com/alicegogogogogo/local-first-sync-service/internal/store"
)

// schema is created when the service is constructed; its shape is unchanged
// from the pre-refactor layout, so authorization rows already on disk stay
// readable.
const schema = `
CREATE TABLE IF NOT EXISTS document_permissions (
	document_id TEXT NOT NULL,
	device_id   TEXT NOT NULL,
	authorized  INTEGER NOT NULL,
	PRIMARY KEY (document_id, device_id)
);
`

// RevokeSink observes a committed revoke. The change event service and the
// CRDT service register themselves to end the affected live subscriptions; a
// sink must not block and must be safe to call after the revoke transaction
// has committed. The permission service depends on this interface alone, so
// the dependency points from the observers toward the verdict and never back.
type RevokeSink interface {
	PermissionRevoked(documentID, deviceID string)
}

// Service is the permission service.
type Service struct {
	db *sql.DB

	mu    sync.Mutex
	sinks []RevokeSink
}

// New constructs the permission service over the shared kernel handle and
// creates its table.
func New(kernel *store.Store) (*Service, error) {
	db := kernel.DB()
	if _, err := db.Exec(schema); err != nil {
		return nil, err
	}
	return &Service{db: db}, nil
}

// AddRevokeSink registers an observer notified after every committed revoke.
// It is called by the composition root while wiring the services, before the
// surface serves requests.
func (s *Service) AddRevokeSink(sink RevokeSink) {
	s.mu.Lock()
	s.sinks = append(s.sinks, sink)
	s.mu.Unlock()
}

// AuthorizedTx is the shared gate: it returns nil when deviceID is registered
// and currently authorized for documentID, store.ErrDeviceNotFound when the
// device is not registered and store.ErrPermissionDenied when its access has
// been revoked. It runs inside the caller's transaction q, so the verdict is
// taken on the same serialized connection as the work it guards, before any
// document content is read.
func (s *Service) AuthorizedTx(q store.DBTX, documentID, deviceID string) error {
	exists, err := store.DeviceExistsTx(q, deviceID)
	if err != nil {
		return err
	}
	if !exists {
		return store.ErrDeviceNotFound
	}
	var stored int
	err = q.QueryRow(
		`SELECT authorized FROM document_permissions WHERE document_id = ? AND device_id = ?`,
		documentID, deviceID,
	).Scan(&stored)
	switch {
	case errors.Is(err, sql.ErrNoRows):
		// No deviation row: devices start authorized.
		return nil
	case err != nil:
		return err
	default:
		if stored == 0 {
			return store.ErrPermissionDenied
		}
		return nil
	}
}

// DeviceAuthorizedTx adapts the shared gate to the change event and CRDT
// services' Gate interface (which names *sql.Tx). The verdict is identical.
func (s *Service) DeviceAuthorizedTx(tx *sql.Tx, documentID, deviceID string) error {
	return s.AuthorizedTx(tx, documentID, deviceID)
}

// SetDocumentPermission grants or revokes deviceID's access to documentID and
// reports whether the stored permission actually changed.
//
// Every device starts authorized for every document, so the first revoke is
// the first write for the pair (changed=true); repeating a state that already
// holds writes nothing and reports changed=false. An unregistered device
// yields store.ErrDeviceNotFound and nothing is written. The lookup and the
// write run in one serialized transaction, so concurrent grant/revoke calls
// each commit completely and the final state matches the last committed
// action. After a revoke commits, every registered sink is notified; a grant
// notifies nothing (a prior revoke already ended the connection stickily).
func (s *Service) SetDocumentPermission(documentID, deviceID string, authorized bool) (changed bool, err error) {
	tx, err := s.db.Begin()
	if err != nil {
		return false, err
	}
	defer func() { _ = tx.Rollback() }()

	exists, err := store.DeviceExistsTx(tx, deviceID)
	if err != nil {
		return false, err
	}
	if !exists {
		return false, store.ErrDeviceNotFound
	}

	current := true // devices start authorized; a row only records a deviation
	var stored int
	err = tx.QueryRow(
		`SELECT authorized FROM document_permissions WHERE document_id = ? AND device_id = ?`,
		documentID, deviceID,
	).Scan(&stored)
	switch {
	case errors.Is(err, sql.ErrNoRows):
		// No row: the default (authorized) holds.
	case err != nil:
		return false, err
	default:
		current = stored != 0
	}
	if current == authorized {
		return false, tx.Commit()
	}

	v := 0
	if authorized {
		v = 1
	}
	if _, err := tx.Exec(
		`INSERT INTO document_permissions (document_id, device_id, authorized) VALUES (?, ?, ?)
		 ON CONFLICT (document_id, device_id) DO UPDATE SET authorized = excluded.authorized`,
		documentID, deviceID, v,
	); err != nil {
		return false, err
	}
	if err := tx.Commit(); err != nil {
		return false, err
	}

	// A grant cannot unblock a subscription (the first revoke already ended
	// it, stickily); only a revoke needs to end live subscriptions.
	if !authorized {
		s.mu.Lock()
		sinks := append([]RevokeSink(nil), s.sinks...)
		s.mu.Unlock()
		for _, sink := range sinks {
			sink.PermissionRevoked(documentID, deviceID)
		}
	}
	return true, nil
}

// DeleteDevicePermissionsTx removes every document-permission ledger row that
// names deviceID, inside the caller's transaction: grants and revokes the
// deregistered device held on documents vanish together with the device. It is
// the permission service's share of device deregistration, run in the same
// serialized transaction as the registration layer's cascade, so the row
// removals and the device deletion commit as one judgment. After the device
// row is gone the default verdict would be "unregistered" anyway; clearing the
// rows guarantees a device that later re-registers the same id starts with no
// inherited authorization state.
func (s *Service) DeleteDevicePermissionsTx(q store.DBTX, deviceID string) error {
	_, err := q.Exec(
		`DELETE FROM document_permissions WHERE device_id = ?`, deviceID,
	)
	return err
}

// DocumentAuthorized reports whether deviceID currently holds permission for
// documentID. Devices start authorized, so an absent row means authorized.
func (s *Service) DocumentAuthorized(documentID, deviceID string) (bool, error) {
	var stored int
	err := s.db.QueryRow(
		`SELECT authorized FROM document_permissions WHERE document_id = ? AND device_id = ?`,
		documentID, deviceID,
	).Scan(&stored)
	switch {
	case errors.Is(err, sql.ErrNoRows):
		return true, nil
	case err != nil:
		return false, err
	default:
		return stored != 0, nil
	}
}

// PermissionEntry is one row of a document's permission ledger: a currently
// registered device id together with its authorization for the document.
type PermissionEntry struct {
	DeviceID   string
	Authorized bool
}

// ListDocumentPermissions is the read-only ledger view of one document: one
// entry per currently registered device, in ascending lexicographic device-id
// order, paged by limit/offset against that same order.
//
// A device with no ledger row starts authorized, so its entry reports
// Authorized=true; a device whose latest committed action was a revoke reports
// false. Deregistered devices carry no device row and their ledger rows were
// removed by the deregistration cascade, so they never appear. An unknown
// document is indistinguishable from one on which every device keeps the
// default: every registered device lists authorized. The read runs in one
// serialized transaction, creates no row, moves no cursor and notifies no sink.
func (s *Service) ListDocumentPermissions(documentID string, limit, offset int64) ([]PermissionEntry, error) {
	tx, err := s.db.Begin()
	if err != nil {
		return nil, err
	}
	defer func() { _ = tx.Rollback() }()

	rows, err := tx.Query(
		`SELECT d.id, COALESCE(p.authorized, 1) AS authorized
		 FROM devices d
		 LEFT JOIN document_permissions p
		   ON p.document_id = ? AND p.device_id = d.id
		 ORDER BY d.id ASC
		 LIMIT ? OFFSET ?`,
		documentID, limit, offset,
	)
	if err != nil {
		return nil, err
	}
	defer func() { _ = rows.Close() }()

	entries := make([]PermissionEntry, 0)
	for rows.Next() {
		var entry PermissionEntry
		var stored int
		if err := rows.Scan(&entry.DeviceID, &stored); err != nil {
			return nil, err
		}
		entry.Authorized = stored != 0
		entries = append(entries, entry)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return entries, tx.Commit()
}

