15	// upgradeRequest builds a GET with a valid WebSocket handshake for the
16	// in-process handler; negative tests strip or alter individual headers.
17	func upgradeRequest(target string) *http.Request {
18		r := httptest.NewRequest(http.MethodGet, target, nil)
19		r.Header.Set("Connection", "Upgrade")
20		r.Header.Set("Upgrade", "websocket")
21		r.Header.Set("Sec-WebSocket-Key", newWSKey())
22		r.Header.Set("Sec-WebSocket-Version", "13")
23		return r
24	}
