296		w, body := doRequest(t, h, http.MethodGet, "/v1/documents/doc/changes?limit=1000")
297		if w.Code != http.StatusOK {
298			t.Fatal(w.Body.String())
299		}
300		rows := body["changes"].([]any)
301		for i, rowAny := range rows {
302			frame := conn.readChange()
303			row := rowAny.(map[string]any)
304			if frame.ID != row["id"] || frame.DeviceID != row["deviceId"] ||
305				frame.Cursor != int64(row["cursor"].(float64)) {
306				t.Fatalf("frame %d = %+v, row = %v", i, frame, row)
307			}
308			var framePayload, rowPayload any
309			_ = json.Unmarshal(frame.Payload, &framePayload)
310			_ = json.Unmarshal(mustJSON(row["payload"]), &rowPayload)
311			if !deepEqualAny(framePayload, rowPayload) {
312				t.Fatalf("payload %d: frame %v != row %v", i, framePayload, rowPayload)
313			}
314		}
315		_ = st
316	}
