695	func httpGet(t *testing.T, srv *httptest.Server, path string) (int, map[string]any) {
696		t.Helper()
697		resp, err := srv.Client().Get(srv.URL + path)
698		if err != nil {
699			t.Fatalf("GET %s: %v", path, err)
700		}
701		defer resp.Body.Close()
702		data, _ := io.ReadAll(resp.Body)
