278	// Counter commits that advance the per-device maximum push immediately in
279	// commit order; idempotent repeats, equal-value new ops and rejected
280	// regressions change no state and push nothing.
281	func TestCRDTSubscribeCounterPushesOnlyRealChanges(t *testing.T) {
282		srv, _ := newWSTestServer(t)
283		setupSession(t, srv, "dev-1", "sess", "doc", 0)
284	
285		conn, hs := dialWS(t, crdtSubscribeURL(srv, "sess", "doc"))
286		if conn == nil {
287			t.Fatalf("status = %d", hs.StatusCode)
288		}
289		defer conn.close()
290	
291		// First ever state: 5.
292		if code := postCRDTOps(t, srv, "doc", crdtCounterBody("dev-1", crdtCounterOp("a1", 5))); code != http.StatusOK {
293			t.Fatalf("submit = %d", code)
294		}
295		if n := crdtCounterValue(t, conn.readCRDTState()); n != 5 {
296			t.Fatalf("frame = %d, want 5", n)
297		}
298	
299		// Idempotent repeat of the same id/value pushes nothing.
300		if code := postCRDTOps(t, srv, "doc", crdtCounterBody("dev-1", crdtCounterOp("a1", 5))); code != http.StatusOK {
301			t.Fatalf("idempotent resubmit = %d", code)
302		}
303		// A new id carrying an equal contribution is accepted but moves no maximum.
304		if code := postCRDTOps(t, srv, "doc", crdtCounterBody("dev-1", crdtCounterOp("a2", 5))); code != http.StatusOK {
305			t.Fatalf("equal-value submit = %d", code)
306		}
307		conn.setReadDeadline(300 * time.Millisecond)
308		if _, _, _, ok := conn.readFrameMaybe(); ok {
309			t.Fatal("an idempotent/equal-value commit pushed a frame")
310		}
311		conn.clearReadDeadline()
312	
313		// A regression is a 409 and pushes nothing.
314		if code := postCRDTOps(t, srv, "doc", crdtCounterBody("dev-1", crdtCounterOp("a3", 4))); code != http.StatusConflict {
315			t.Fatalf("regression = %d, want 409", code)
316		}
317		// A wholly invalid batch is a 400 and pushes nothing.
318		if code := postCRDTOps(t, srv, "doc", map[string]any{"deviceId": "dev-1", "type": "counter", "ops": []any{}}); code != http.StatusBadRequest {
319			t.Fatalf("empty batch = %d, want 400", code)
320		}
321		conn.setReadDeadline(300 * time.Millisecond)
322		if _, _, _, ok := conn.readFrameMaybe(); ok {
323			t.Fatal("a rejected commit pushed a frame")
324		}
325		conn.clearReadDeadline()
326	
327		// An advancing contribution pushes the new sum.
328		if code := postCRDTOps(t, srv, "doc", crdtCounterBody("dev-1", crdtCounterOp("a4", 8))); code != http.StatusOK {
329			t.Fatalf("advance = %d", code)
330		}
331		if n := crdtCounterValue(t, conn.readCRDTState()); n != 8 {
332			t.Fatalf("frame = %d, want 8", n)
333		}
334	
335		// A second device adds its maximum to the sum.
336		registerDeviceViaHTTP(t, srv, "dev-2")
337		if code := postCRDTOps(t, srv, "doc", crdtCounterBody("dev-2", crdtCounterOp("b1", 3))); code != http.StatusOK {
338			t.Fatalf("dev-2 submit = %d", code)
339		}
340		if n := crdtCounterValue(t, conn.readCRDTState()); n != 11 {
341			t.Fatalf("frame = %d, want 11", n)
342		}
343	}
