554			"deviceId": "dev-1", "action": "revoke",
555		}); code != http.StatusOK {
556			t.Fatalf("revoke = %d", code)
557		}
558		if code := postHTTP(t, srv, "/v1/documents/doc/permissions", map[string]any{
559			"deviceId": "dev-1", "action": "grant",
560		}); code != http.StatusOK {
561			t.Fatalf("grant = %d", code)
562		}
563		conn.setReadDeadline(2 * time.Second)
564		if code := conn.readCloseCode(); code != 4403 {
565			t.Fatalf("close code = %d, want sticky 4403 despite grant", code)
566		}
567		conn.clearReadDeadline()
568	}
569	
570	// The termination signal ends the subscription with 1001 and committed state
571	// stays readable.
572	func TestCRDTSubscribeShutdownCloses1001(t *testing.T) {
573		srv, st := newWSTestServer(t)
574		setupSession(t, srv, "dev-1", "sess", "doc", 0)
575		if code := postCRDTOps(t, srv, "doc", crdtCounterBody("dev-1", crdtCounterOp("a1", 7))); code != http.StatusOK {
576			t.Fatalf("submit = %d", code)
577		}
578	
579		conn, hs := dialWS(t, crdtSubscribeURL(srv, "sess", "doc"))
580		if conn == nil {
581			t.Fatalf("status = %d", hs.StatusCode)
582		}
583		defer conn.close()
584		if n := crdtCounterValue(t, conn.readCRDTState()); n != 7 {
585			t.Fatalf("initial = %d, want 7", n)
586		}
587	
588		st.InterruptWaits()
589		conn.setReadDeadline(2 * time.Second)
590		if code := conn.readCloseCode(); code != 1001 {
591			t.Fatalf("close code = %d, want 1001", code)
592		}
593		conn.clearReadDeadline()
594	
595		state, err := st.GetCRDTState("doc")
596		if err != nil {
597			t.Fatalf("state after signal: %v", err)
598		}
599		if state.Type != "counter" || string(state.Value) != "7" {
600			t.Fatalf("committed state after signal = %+v", state)
601		}
602	}
603	
604	// The connection is push-only: inbound data frames are discarded and cannot
605	// submit CRDT operations; ping is answered with pong and the stream continues.
606	func TestCRDTSubscribePushOnlyAndPingPong(t *testing.T) {
607		srv, st := newWSTestServer(t)
608		setupSession(t, srv, "dev-1", "sess", "doc", 0)
609		if code := postCRDTOps(t, srv, "doc", crdtCounterBody("dev-1", crdtCounterOp("a1", 1))); code != http.StatusOK {
610			t.Fatalf("submit = %d", code)
611		}
612	
613		conn, hs := dialWS(t, crdtSubscribeURL(srv, "sess", "doc"))
614		if conn == nil {
615			t.Fatalf("status = %d", hs.StatusCode)
616		}
617		defer conn.close()
618		if n := crdtCounterValue(t, conn.readCRDTState()); n != 1 {
619			t.Fatalf("initial = %d", n)
620		}
621	
622		conn.sendText(`{"deviceId":"dev-1","type":"counter","ops":[{"id":"forged","value":99}]}`)
623		conn.sendPing()
624	
625		conn.setReadDeadline(2 * time.Second)
626		sawPong := false
627		for {
628			fin, opcode, _, ok := conn.readFrameMaybe()
629			if !ok {
630				break
631			}
632			if opcode == wsOpcodePong && fin {
633				sawPong = true
634				break
635			}
636			if opcode == wsOpcodeText {
637				t.Fatal("the server pushed a state after a discarded client frame")
638			}
639		}
640		conn.clearReadDeadline()
641		if !sawPong {
642			t.Fatal("no pong received for the ping")
643		}
644	
645		// The forged op never reached the CRDT tables: value still 1, op id free.
646		state, err := st.GetCRDTState("doc")
647		if err != nil {
648			t.Fatal(err)
649		}
650		if string(state.Value) != "1" {
651			t.Fatalf("state = %s, want 1 (client frame was applied)", state.Value)
652		}
653		results, err := st.SubmitCRDTOps("doc", crdt.TypeCounter, []crdt.Op{
654			{ID: "forged", DeviceID: "dev-1", Value: json.RawMessage(`99`)},
655		})
656		if err != nil {
657			t.Fatalf("forged id should be free: %v", err)
658		}
659		if !results[0].Created {
660			t.Fatal("forged id already existed: a client frame was written")
661		}
662		if n := crdtCounterValue(t, conn.readCRDTState()); n != 99 {
663			t.Fatalf("frame after real submit = %d, want 99", n)
664		}
665	}
666	
667	// CRDT pushes use neither the change-log cursor nor the changes subscription,
668	// and a CRDT state subscription receives no change-log commits.
669	func TestCRDTSubscribeIndependentOfChangeLog(t *testing.T) {
670		srv, _ := newWSTestServer(t)
671		setupSession(t, srv, "dev-1", "sess", "doc", 1)
672	
673		crdtConn, hs := dialWS(t, crdtSubscribeURL(srv, "sess", "doc"))
674		if crdtConn == nil {
675			t.Fatalf("crdt subscribe status = %d", hs.StatusCode)
676		}
677		defer crdtConn.close()
678		changeConn, hs2 := dialWS(t, subscribeURL(srv, "sess", "doc", "1"))
679		if changeConn == nil {
680			t.Fatalf("changes subscribe status = %d", hs2.StatusCode)
681		}
682		defer changeConn.close()
683	
684		// A CRDT op reaches only the state subscription.
685		if code := postCRDTOps(t, srv, "doc", crdtCounterBody("dev-1", crdtCounterOp("a1", 2))); code != http.StatusOK {
686			t.Fatalf("submit = %d", code)
687		}
688		if n := crdtCounterValue(t, crdtConn.readCRDTState()); n != 2 {
689			t.Fatalf("crdt frame = %d, want 2", n)
690		}
691		changeConn.setReadDeadline(300 * time.Millisecond)
692		if _, _, _, ok := changeConn.readFrameMaybe(); ok {
693			t.Fatal("a crdt op woke the changes subscription")
694		}
695		changeConn.clearReadDeadline()
696	
697		// A change commit reaches only the changes subscription.
698		postDocChange(t, srv, "dev-1", "doc", "c2", map[string]any{"n": 2})
699		if c := changeConn.readChange(); c.ID != "c2" || c.Cursor != 2 {
700			t.Fatalf("change frame = %+v, want c2/2", c)
701		}
702		crdtConn.setReadDeadline(300 * time.Millisecond)
703		if _, _, _, ok := crdtConn.readFrameMaybe(); ok {
704			t.Fatal("a change commit woke the crdt state subscription")
705		}
706		crdtConn.clearReadDeadline()
707	}
708	
709	// Identifiers literally named after the endpoint keywords keep ordinary
710	// behavior: a document named "crdt" and one named "state" still subscribe.
711	func TestCRDTSubscribeKeywordIdentifiers(t *testing.T) {
712		srv, _ := newWSTestServer(t)
713		setupSession(t, srv, "dev-1", "sess", "crdt", 0)
714		if code := postCRDTOps(t, srv, "crdt", crdtCounterBody("dev-1", crdtCounterOp("a1", 3))); code != http.StatusOK {
715			t.Fatalf("submit to doc crdt = %d", code)
716		}
717		conn, hs := dialWS(t, crdtSubscribeURL(srv, "sess", "crdt"))
718		if conn == nil {
719			t.Fatalf("subscribe to doc crdt status = %d", hs.StatusCode)
720		}
721		defer conn.close()
722		if n := crdtCounterValue(t, conn.readCRDTState()); n != 3 {
723			t.Fatalf("frame = %d, want 3", n)
724		}
725	}
726	
727	// mustReadBody performs a GET through the test server and returns the raw body.
728	func mustReadBody(t *testing.T, srv *httptest.Server, path string) string {
729		t.Helper()
730		resp, err := srv.Client().Get(srv.URL + path)
731		if err != nil {
732			t.Fatalf("GET %s: %v", path, err)
733		}
734		defer resp.Body.Close()
735		data, err := io.ReadAll(resp.Body)
736		if err != nil {
737			t.Fatal(err)
738		}
739		return string(data)
740	}
741	
742	// registerDeviceViaHTTP registers a device through the public HTTP surface.
743	func registerDeviceViaHTTP(t *testing.T, srv *httptest.Server, device string) {
744		t.Helper()
745		if code := postHTTP(t, srv, "/v1/devices", map[string]any{"deviceId": device}); code != http.StatusOK {
746			t.Fatalf("register %s = %d", device, code)
747		}
748	}
749	
750	func crdtRegisterOp(id string, version int, value any) map[string]any {
751		return map[string]any{"id": id, "version": version, "value": value}
752	}
753	
754	// Register commits that move the winning value push immediately; idempotent
755	// repeats, losing (lower-version) ops carrying an already-winning value, and
756	// rejected stalls change no state and push nothing.
757	func TestCRDTSubscribeRegisterPushesOnlyRealChanges(t *testing.T) {
758		srv, _ := newWSTestServer(t)
759		setupSession(t, srv, "dev-1", "sess", "doc", 0)
760	
761		conn, hs := dialWS(t, crdtSubscribeURL(srv, "sess", "doc"))
762		if conn == nil {
763			t.Fatalf("status = %d, want 101", hs.StatusCode)
764		}
765		defer conn.close()
766	
767		// First ever state: the v1 string.
768		if code := postCRDTOps(t, srv, "doc", crdtRegisterBody("dev-1", crdtRegisterOp("a1", 1, "one"))); code != http.StatusOK {
769			t.Fatalf("submit = %d", code)
770		}
771		state := conn.readCRDTState()
772		if state.Type != "register" || string(state.Value) != `"one"` {
773			t.Fatalf("frame = %s %s, want register \"one\"", state.Type, state.Value)
774		}
775	
776		// Idempotent repeat of the same op pushes nothing.
777		if code := postCRDTOps(t, srv, "doc", crdtRegisterBody("dev-1", crdtRegisterOp("a1", 1, "one"))); code != http.StatusOK {
778			t.Fatalf("idempotent resubmit = %d", code)
779		}
780		// A stalled version is a 409 and pushes nothing.
781		if code := postCRDTOps(t, srv, "doc", crdtRegisterBody("dev-1", crdtRegisterOp("a2", 1, "stall"))); code != http.StatusConflict {
782			t.Fatalf("stall = %d, want 409", code)
783		}
784		conn.setReadDeadline(300 * time.Millisecond)
785		if _, _, _, ok := conn.readFrameMaybe(); ok {
786			t.Fatal("an idempotent/rejected commit pushed a frame")
787		}
788		conn.clearReadDeadline()
789	
790		// A greater version pushes the new winning value.
791		if code := postCRDTOps(t, srv, "doc", crdtRegisterBody("dev-1", crdtRegisterOp("a3", 2, "two"))); code != http.StatusOK {
792			t.Fatalf("advance = %d", code)
793		}
794		state = conn.readCRDTState()
795		if string(state.Value) != `"two"` {
796			t.Fatalf("frame = %s, want \"two\"", state.Value)
797		}
798	
799		// A new op that loses the merge (lower version from another device) is
800		// accepted but pushes nothing.
801		registerDeviceViaHTTP(t, srv, "dev-2")
802		if code := postCRDTOps(t, srv, "doc", crdtRegisterBody("dev-2", crdtRegisterOp("b1", 1, "loser"))); code != http.StatusOK {
803			t.Fatalf("losing submit = %d", code)
804		}
805		conn.setReadDeadline(300 * time.Millisecond)
806		if _, _, _, ok := conn.readFrameMaybe(); ok {
807			t.Fatal("a losing op pushed a frame")
808		}
809		conn.clearReadDeadline()
810	
811		// A version tie goes to the smaller op id and pushes the new winner.
812		if code := postCRDTOps(t, srv, "doc", crdtRegisterBody("dev-2", crdtRegisterOp("a0", 2, "tie-winner"))); code != http.StatusOK {
813			t.Fatalf("tie submit = %d", code)
814		}
815		state = conn.readCRDTState()
816		if string(state.Value) != `"tie-winner"` {
817			t.Fatalf("frame = %s, want \"tie-winner\"", state.Value)
818		}
819	}
